	body, err := json.Marshal(cfg.payload.toMap())
	if err != nil {
		return nil, fmt.Errorf("encode request: %w", err)
	}

	resp, err := s.client.gen.AddCallLogWithBody(ctx, "application/json", bytes.NewReader(body), toRequestEditors(editors)...)
