package v1

import (
	"context"
	"io"
	"mime/multipart"
	"net/http"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/juhokoskela/pipedrive-go/pipedrive"
)

func TestRepro_UploadRetry(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "doc.txt")
	if err := os.WriteFile(path, []byte("hello upload"), 0o600); err != nil {
		t.Fatal(err)
	}

	var calls int
	client := newTestClientWithConfig(t, pipedrive.Config{
		RetryPolicy: &pipedrive.RetryPolicy{
			MaxAttempts:     3,
			BaseDelay:       time.Millisecond,
			MaxDelay:        time.Millisecond,
			RetryAllMethods: true,
		},
	}, func(w http.ResponseWriter, r *http.Request) {
		calls++
		if calls == 1 {
			w.WriteHeader(http.StatusTooManyRequests)
			_, _ = w.Write([]byte(`{"success":false,"error":"rate limited"}`))
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"doc.txt"}}`))
	})

	// User pattern: open a real file, build multipart body themselves.
	f, err := os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()

	body, contentType := buildMultipart(t, f)
	_, err = client.Files.Add(context.Background(), body, contentType)
	t.Logf("attempt count: %d, err: %v", calls, err)
	if calls < 2 {
		t.Fatalf("expected retry, got %d calls", calls)
	}
}

func buildMultipart(t *testing.T, f *os.File) (io.Reader, string) {
	t.Helper()
	pr, pw := io.Pipe()
	w := multipart.NewWriter(pw)
	go func() {
		defer pw.Close()
		part, err := w.CreateFormFile("file", "doc.txt")
		if err != nil {
			_ = pw.CloseWithError(err)
			return
		}
		if _, err := io.Copy(part, f); err != nil {
			_ = pw.CloseWithError(err)
			return
		}
		_ = w.Close()
	}()
	return pr, w.FormDataContentType()
}

