func TestFilesService_AddFile_RetriesOn429WithNonSeekableContent(t *testing.T) {
	t.Parallel()

	uploads := make(chan uploadObservation, 4)
	client := newTestClientWithConfig(t, pipedrive.Config{
		RetryPolicy: &pipedrive.RetryPolicy{
			MaxAttempts:     3,
			BaseDelay:       time.Millisecond,
			MaxDelay:        time.Millisecond,
			RetryAllMethods: true,
		},
	}, func(w http.ResponseWriter, r *http.Request) {
		body, err := io.ReadAll(r.Body)
		if err != nil {
			t.Errorf("read request body: %v", err)
		}
		uploads <- uploadObservation{
			contentType: r.Header.Get("Content-Type"),
			body:        body,
		}

		if len(uploads) == 1 {
			w.Header().Set("Retry-After", "0")
			w.WriteHeader(http.StatusTooManyRequests)
			_, _ = w.Write([]byte(`{"success":false,"error":"rate limited"}`))
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":77,"name":"doc.txt"}}`))
	})

	// A pipe mirrors callers that stream file content straight from disk
	// (os.Open + io.Copy) instead of pre-buffering it.
	content, contentWriter := io.Pipe()
	go func() {
		_, _ = contentWriter.Write([]byte("streamed upload body"))
		_ = contentWriter.Close()
	}()

	file, err := client.Files.AddFile(context.Background(), "doc.txt", content)
	if err != nil {
		t.Fatalf("AddFile error: %v", err)
	}
	if file.ID != 77 {
		t.Fatalf("unexpected file: %#v", file)
	}
	close(uploads)

	var attempts []uploadObservation
	for obs := range uploads {
		attempts = append(attempts, obs)
	}
	if len(attempts) != 2 {
		t.Fatalf("expected 2 attempts, got %d", len(attempts))
	}

	for i, obs := range attempts {
		form, err := parseMultipartForm(obs.contentType, obs.body)
		if err != nil {
			t.Fatalf("attempt %d: parse multipart: %v", i+1, err)
		}
		if got := form.File["file"][0].Filename; got != "doc.txt" {
			t.Fatalf("attempt %d: unexpected file name: %q", i+1, got)
		}
		content, err := io.ReadAll(form.File["file"][0])
		if err != nil {
			t.Fatalf("attempt %d: read file part: %v", i+1, err)
		}
		if string(content) != "streamed upload body" {
			t.Fatalf("attempt %d: incomplete replayed body: %q", i+1, string(content))
		}
	}
	if string(attempts[0].body) != string(attempts[1].body) {
		t.Fatal("expected identical bodies across retry attempts")
	}
}

