display.text:
type FilesService struct {
	client *Client
}

type FilesOption interface {
	applyFiles(*filesOptions)
}

// AddFileOption customizes FilesService.AddFile calls.
type AddFileOption interface {
	applyAddFile(*addFileOptions)
}

// FilesRequestOption applies to every FilesService operation.
type FilesRequestOption interface {
	FilesOption
	AddFileOption
}

type filesOptions struct {
	query          url.Values
	requestOptions []pipedrive.RequestOption
}

type addFileOptions struct {
	payload        addFilePayload
	requestOptions []pipedrive.RequestOption
}

type addFilePayload struct {
	dealID     *DealID
	personID   *PersonID
	orgID      *OrganizationID
	productID  *ProductID
	activityID *ActivityID
	leadID     *LeadID
	projectID  *ProjectID
}

type filesOptionFunc func(*filesOptions)

func (f filesOptionFunc) applyFiles(cfg *filesOptions) {
	f(cfg)
}

type filesRequestOptions struct {
	requestOptions []pipedrive.RequestOption
}

func (o filesRequestOptions) applyFiles(cfg *filesOptions) {
	cfg.requestOptions = append(cfg.requestOptions, o.requestOptions...)
}

func (o filesRequestOptions) applyAddFile(cfg *addFileOptions) {
	cfg.requestOptions = append(cfg.requestOptions, o.requestOptions...)
}

type addFileFieldOption func(*addFilePayload)

func (f addFileFieldOption) applyAddFile(cfg *addFileOptions) {
	f(&cfg.payload)
}

func WithFilesQuery(values url.Values) FilesOption {
	return filesOptionFunc(func(cfg *filesOptions) {
		cfg.query = mergeQueryValues(cfg.query, values)
	})
}

func WithFilesRequestOptions(opts ...pipedrive.RequestOption) FilesRequestOption {
	return filesRequestOptions{requestOptions: opts}
}

// WithFileDealID associates the uploaded file with a deal.
func WithFileDealID(id DealID) AddFileOption {
	return addFileFieldOption(func(payload *addFilePayload) {
		payload.dealID = &id
	})
}

// WithFilePersonID associates the uploaded file with a person.
func WithFilePersonID(id PersonID) AddFileOption {
	return addFileFieldOption(func(payload *addFilePayload) {
		payload.personID = &id
	})
}

// WithFileOrganizationID associates the uploaded file with an organization.
func WithFileOrganizationID(id OrganizationID) AddFileOption {
	return addFileFieldOption(func(payload *addFilePayload) {
		payload.orgID = &id
	})
}

// WithFileProductID associates the uploaded file with a product.
func WithFileProductID(id ProductID) AddFileOption {
	return addFileFieldOption(func(payload *addFilePayload) {
		payload.productID = &id
	})
